import copy,json; from work import evaluate

def check(req,pol,expected):
 a=copy.deepcopy(req); b=copy.deepcopy(pol); got=evaluate(req,pol); assert got==expected,(req,got,expected); assert req==a and pol==b
p={'edges':{'a>b':{},'b>c':{'role':'op'}},'retry_limit':2}
check({'from':'a','to':'x'},p,{'ok':False,'value':None,'reason':'blocked'})
check({'from':'b','to':'c','role':'bad','attempts':9},p,{'ok':False,'value':None,'reason':'permission'})
for n in (0,1): check({'from':'a','to':'b','attempts':n},p,{'ok':True,'value':'b','reason':'ok'})
for n in (-1,2,True,False,1.0,'1',None): check({'from':'a','to':'b','attempts':n},p,{'ok':False,'value':None,'reason':'retry_limit'})
requests=json.load(open('requests.json')); policy=json.load(open('policy.json')); actual=[evaluate(x,policy) for x in requests]; assert actual==json.load(open('report.json')); print('all checks passed')

